From 55045cfcb9290ac8e09b798732196adf2d36e9e8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:26:31 +0100
Subject: [PATCH] applets/notifications: say when Do Not Disturb was due to
 fullscreen

The summary of notifications missed during Do Not Disturb never said why
it was on, which is confusing when it was turned on by a fullscreen app.
Track whether only fullscreen inhibited them and mention it in the text.

BUG: 507073
---
 applets/notifications/global/Globals.qml | 37 +++++++++++++++++++-----
 libnotificationmanager/notifications.cpp | 21 ++++++++++----
 libnotificationmanager/notifications.h   |  7 ++++-
 3 files changed, 52 insertions(+), 13 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..d9eae21159 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -31,15 +31,30 @@ QtObject {
     signal timeChanged

     property bool inhibited: false
+    // Inhibited for any reason other than a focused fullscreen window
+    property bool inhibitedNotByFullscreen: false
+    // Whether Do Not Disturb has only been active because of a focused fullscreen window since it was turned on
+    property bool inhibitedOnlyByFullscreen: false
+
+    onInhibitedNotByFullscreenChanged: {
+        if (inhibitedNotByFullscreen) {
+            inhibitedOnlyByFullscreen = false;
+        }
+    }

     onInhibitedChanged: {
         // Explicitly update server state before potentially sending a inhibition summary,
         // so it's not considered "added while inhibited" and shown in history unwanted.
         NotificationManager.Server.inhibited = inhibited;

-        if (!inhibited) {
+        if (inhibited) {
+            inhibitedOnlyByFullscreen = !inhibitedNotByFullscreen;
+        } else {
             const urgency = notificationSettings.lowPriorityHistory ? NotificationManager.Notifications.LowUrgency : NotificationManager.Notifications.NormalUrgency;
-            popupNotificationsModel.showInhibitionSummary(urgency, notificationSettings.popupBlacklistedApplications, notificationSettings.popupBlacklistedServices);
+            popupNotificationsModel.showInhibitionSummary(urgency,
+                                                          notificationSettings.popupBlacklistedApplications,
+                                                          notificationSettings.popupBlacklistedServices,
+                                                          inhibitedOnlyByFullscreen);
         }

         var pa = pulseAudio.item;
@@ -273,7 +288,7 @@ QtObject {
     }

     function checkInhibition() {
-        globals.inhibited = Qt.binding(function() {
+        globals.inhibitedNotByFullscreen = Qt.binding(function() {
             var inhibited = false;

             if (!NotificationManager.Server.valid) {
@@ -289,16 +304,24 @@ QtObject {
                 inhibited |= true;
             }

-            if (notificationSettings.inhibitNotificationsWhenFullscreen) {
-                inhibited |= notificationSettings.fullscreenFocused;
-            }
-
             if (notificationSettings.inhibitNotificationsWhenScreensMirrored) {
                 inhibited |= notificationSettings.screensMirrored;
             }

             return inhibited;
         });
+
+        globals.inhibited = Qt.binding(function() {
+            if (!NotificationManager.Server.valid) {
+                return false;
+            }
+
+            if (notificationSettings.inhibitNotificationsWhenFullscreen && notificationSettings.fullscreenFocused) {
+                return true;
+            }
+
+            return globals.inhibitedNotByFullscreen;
+        });
     }

     function revokeInhibitions() {
diff --git a/libnotificationmanager/notifications.cpp b/libnotificationmanager/notifications.cpp
index baa61cecc9..764874de1f 100644
--- a/libnotificationmanager/notifications.cpp
+++ b/libnotificationmanager/notifications.cpp
@@ -977,7 +977,10 @@ void Notifications::collapseAllGroups()
     }
 }

-void Notifications::showInhibitionSummary(Urgency urgency, const QStringList &blacklistedDesktopEntries, const QStringList &blacklistedNotifyRcNames)
+void Notifications::showInhibitionSummary(Urgency urgency,
+                                          const QStringList &blacklistedDesktopEntries,
+                                          const QStringList &blacklistedNotifyRcNames,
+                                          bool inhibitedByFullscreen)
 {
     int inhibited = 0;
     for (int i = 0, count = d->notificationsAndJobsModel->rowCount(); i < count; ++i) {
@@ -1014,10 +1017,18 @@ void Notifications::showInhibitionSummary(Urgency urgency, const QStringList &bl

     d->inhibitionSummaryNotification = new KNotification(u"inhibitionSummary"_s);
     d->inhibitionSummaryNotification->setTitle(i18ncp("@title", "Unread Notification", "Unread Notifications", inhibited));
-    d->inhibitionSummaryNotification->setText(i18ncp("@info",
-                                                     "%1 notification was received while Do Not Disturb was active.",
-                                                     "%1 notifications were received while Do Not Disturb was active.",
-                                                     inhibited));
+    if (inhibitedByFullscreen) {
+        d->inhibitionSummaryNotification->setText(
+            i18ncp("@info",
+                   "%1 notification was received while Do Not Disturb was active because a fullscreen application was focused.",
+                   "%1 notifications were received while Do Not Disturb was active because a fullscreen application was focused.",
+                   inhibited));
+    } else {
+        d->inhibitionSummaryNotification->setText(i18ncp("@info",
+                                                         "%1 notification was received while Do Not Disturb was active.",
+                                                         "%1 notifications were received while Do Not Disturb was active.",
+                                                         inhibited));
+    }
     d->inhibitionSummaryNotification->setIconName(u"preferences-desktop-notification-bell"_s);
     d->inhibitionSummaryNotification->setFlags(KNotification::CloseOnTimeout);
     d->inhibitionSummaryNotification->setComponentName(u"libnotificationmanager"_s);
diff --git a/libnotificationmanager/notifications.h b/libnotificationmanager/notifications.h
index 25b62c1ea0..f4a8490edd 100644
--- a/libnotificationmanager/notifications.h
+++ b/libnotificationmanager/notifications.h
@@ -584,8 +584,13 @@ public:

     /**
      * Shows a notification to report the number of unread inhibited notifications.
+     *
+     * @param inhibitedByFullscreen Whether Do Not Disturb was only active because a fullscreen application was focused. @since 6.9
      */
-    Q_INVOKABLE void showInhibitionSummary(Urgency urgency, const QStringList &blacklistedDesktopEntries, const QStringList &blacklistedNotifyRcNames);
+    Q_INVOKABLE void showInhibitionSummary(Urgency urgency,
+                                           const QStringList &blacklistedDesktopEntries,
+                                           const QStringList &blacklistedNotifyRcNames,
+                                           bool inhibitedByFullscreen = false);

     /**
      * Hides the notification about the number of unread inhibited notifications.
-- 
